import { useCallback, useEffect, useState } from 'react'

import type { ExpenseViewModel, NewExpense, SubmitExpenseResult } from '../../application/ExpenseViewModel'
import { useExpenseUseCases } from '../useExpenseUseCases/useExpenseUseCases'

export const useExpenses = () => {
  const { listExpenses, submitExpense } = useExpenseUseCases()
  const [expenses, setExpenses] = useState<ExpenseViewModel[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    let active = true
    listExpenses
      .execute()
      .then((items) => {
        if (active) setExpenses(items)
      })
      .catch((e: unknown) => {
        if (active) setError(e instanceof Error ? e.message : 'Could not load expenses')
      })
      .finally(() => {
        if (active) setLoading(false)
      })
    return () => {
      active = false
    }
  }, [listExpenses])

  const submit = useCallback(
    async (expense: NewExpense): Promise<SubmitExpenseResult> => {
      const result = await submitExpense.execute(expense)
      if (result.ok) setExpenses((current) => [...current, result.expense])
      return result
    },
    [submitExpense],
  )

  return { expenses, loading, error, submit }
}
