export const ExpensesPage = () => {
  const { expenses, loading, error, submit } = useExpenses()

  return (
    <main>
      <h1>My expenses</h1>
      {loading && <p>Loading…</p>}
      {error && <p role="alert">{error}</p>}
      {!loading && !error && expenses.length === 0 && <p>No expenses yet.</p>}
      {expenses.length > 0 && (
        <ul>
          {expenses.map((expense) => (
            <li key={expense.id}>
              {expense.label} — {expense.amount} {expense.currency} ({expense.status})
            </li>
          ))}
        </ul>
      )}
      <h2>New expense</h2>
      <ExpenseForm onSubmit={submit} />
    </main>
  )
}
